arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H 'Authorization: Bearer <TOKEN>' -d 'channel=C_ENG&limit=999' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit()
for m in d['messages']:
    rx = m.get('reactions', [])
    if any(r['name']=='eyes' for r in rx):
        print(m['ts'], m.get('user'), repr(m.get('text','')[:120]), [(r['name'], r['users']) for r in rx])
"

